100:   const msg = err?.message || '';
101:   const htrUid = hathorLib.constants.NATIVE_TOKEN_UID;
102:   if (msg.includes(`No UTXOs available for the token ${htrUid}`)) {
103:     return t`Insufficient HTR to cover the network fee.`;
104:   }
105:   if (msg.includes('No UTXOs available for the token')) {
106:     return t`Insufficient balance to send this transaction.`;
107:   }
108:   const insufficientTokens = INSUFFICIENT_TOKENS_ERROR.exec(msg);
109:   if (insufficientTokens) {
110:     // HTR pays the fees: for HTR, they count with the amount.
111:     return insufficientTokens[1] === htrUid
112:       ? t`Insufficient HTR to cover this transaction and its fees.`
113:       : t`Insufficient balance to send this transaction.`;
114:   }
